        lib.set_prof(ctypes.c_void_p(prof.data_ptr())); prof.zero_(); fn(emb,W,bias,*outs); torch.cuda.synchronize(); lib.set_prof(ctypes.c_void_p(0))
        pr=prof.view(-1,4)[:72*(1 if B<=512 else 2)].cpu().double()
        for o in outs: o.zero_()
        fn(emb,W,bias,*outs); torch.cuda.synchronize()
        d=(torch.cat(outs,1).double()-ref).abs(); bad=int((d>2e-3+1e-5*ref.abs()).sum())
        mhz=1e3/statistics.median((pr[:,3]/2**20).tolist())
        res.append(f"{n}:{us:.1f}us kb={statistics.median(pr[:,1].tolist())/48:.0f} {mhz:.0f}MHz e={d.max().item():.2e} bad={bad}")
    print(B,' | '.join(res))

